            ComputeAqlQueueSessionErrorV1::DispatchBinding(
                Gfx942DispatchBindingErrorV1::InvalidData {
                    index: 1,
                    detail: "detached returning-destroy storage identity",
                }
            )
        ));
        assert!(poisoned);
    }

