            NativeQueueAdapterErrorV1::MalformedKernelResult(
                NativeQueueOperationV1::Create,
                "CREATE_QUEUE outputs",
            ),
            ComputeAqlQueuePhaseV1::Ambiguous,
        ),
        (
            success(Mutation::CreateDoorbell(encoded_doorbell(28_851, 1))),
            NativeQueueAdapterErrorV1::MalformedKernelResult(
