    }

    pub(crate) fn checked_gpu_subrange(
        &self,
        offset: u64,
        byte_len: u64,
        alignment: u64,
    ) -> Option<u64> {
        if byte_len == 0
            || alignment == 0
            || !alignment.is_power_of_two()
            || !offset.is_multiple_of(alignment)
