    #[test]
    fn final_restore_revokes_certificate_and_allows_fresh_queue_transfer() {
        let (identity, memory, device, vm) = transferred_model_foundation();
        let domain = memory.domain_id();
        let mut foundation = QueueModelFoundationV1::uncertified(identity, memory);
        let mut session_foundation = QueueModelFoundationV1::empty(domain);
        let mut ownership = QueueModelOwnershipV1::new();
        let first = ownership
            .certify_and_transfer_to_queue(&mut foundation, 37, device, vm)
            .unwrap();
        let first_loan = ownership
            .loan_foundation(37, &mut session_foundation, &mut foundation, device, vm)
            .unwrap();
        let stale_first_loan = LiveQueueModelFoundationLoanV1 {
            session_id: first_loan.session_id,
            issuer: first_loan.issuer,
            generation: first_loan.generation,
            starting_revision: first_loan.starting_revision,
        };
        ownership
            .reclaim_foundation(
                37,
                &mut session_foundation,
                &mut foundation,
                device,
                vm,
                first_loan,
            )
            .unwrap();
        foundation.validate_full(37, device, vm, first).unwrap();
        ownership.restore_to_session(first).unwrap();
        foundation
            .revoke_invariant_certificate(37, device, vm, first)
            .unwrap();
        assert!(!foundation.is_certified_for_test());

        let second = ownership
            .certify_and_transfer_to_queue(&mut foundation, 37, device, vm)
            .unwrap();
        assert_ne!(first, second);
        let second_loan = ownership
            .loan_foundation(37, &mut session_foundation, &mut foundation, device, vm)
            .unwrap();
        assert_eq!(second_loan.generation, 1);
        assert_eq!(second_loan.issuer, second);
        assert!(
            ownership
                .reclaim_foundation(
                    37,
                    &mut session_foundation,
                    &mut foundation,
                    device,
                    vm,
                    stale_first_loan,
                )
                .is_err()
        );
        ownership
            .reclaim_foundation(
                37,
                &mut session_foundation,
                &mut foundation,
                device,
                vm,
                second_loan,
            )
            .unwrap();
        assert_eq!(
            ownership.phase,
            QueueModelOwnershipPhaseV1::QueueOwned { issuer: second }
        );
    }

    struct BackingConstructorFixture {
        engine: SharedMemoryEngine<FakeBackend>,
        ownership: QueueModelOwnershipV1,
        foundation: QueueModelFoundationV1,
        device: ModelDeviceAdmissionV1,
        vm: VmKeyV1,
    }

    impl BackingConstructorFixture {
        fn new(budget: Option<Gfx942DeviceBackingBudgetV1>) -> Self {
            Self::with_aperture(budget, 0x20_0000)
        }

        fn with_aperture(budget: Option<Gfx942DeviceBackingBudgetV1>, bytes: u64) -> Self {
            let (identity, memory, device, vm) = transferred_model_foundation_with_aperture(bytes);
            let mut fixture = Self {
                engine: acquired(),
                ownership: QueueModelOwnershipV1::new(),
                foundation: QueueModelFoundationV1::uncertified(identity, memory),
                device,
                vm,
            };
            fixture.configure(budget).unwrap();
            fixture
        }

        fn configure(
            &mut self,
            budget: Option<Gfx942DeviceBackingBudgetV1>,
        ) -> Result<(), MemorySessionError> {
            self.ownership.configure_optional_device_backing_budget(
                &mut self.engine,
                self.device,
                self.vm,
                budget,
            )
        }

        fn transfer(
            &mut self,
            authorities: &[&Gfx942DeviceMemoryDispatchAuthorityV1],
        ) -> Result<QueueModelFoundationV1, MemorySessionError> {
            self.engine.validate_complete_dispatch_device_memory_set(
                authorities,
                self.device.model_key(),
                self.vm,
            )?;
            self.ownership.take_foundation(
                &mut self.engine,
                &mut self.foundation,
                self.device,
                self.vm,
            )
        }

        fn mapped_device(&mut self) -> Gfx942DeviceMemoryDispatchAuthorityV1 {
            let lease = self
                .engine
                .allocate_device_memory(self.device.model_key(), self.vm, 17, 4)
                .and_then(|lease| self.engine.map_device_memory(lease))
                .unwrap();
            let record = &self.engine.device_memory[0];
            Gfx942DeviceMemoryDispatchAuthorityV1 {
                facts: Gfx942DeviceMemoryDispatchFactsV1 {
                    id: record.id,
                    generation: record.generation,
                    device: record.device,
                    vm: record.vm,
                    gpu_va: record.gpu_va,
                    layout: record.layout,
                },
                lease,
            }
        }

        fn usage(&self) -> Option<Gfx942DeviceBackingUsageV1> {
            self.engine
                .device_backing_account
                .as_ref()
                .map(DeviceBackingAccountV1::usage)
        }
    }

